('lookout', 'Vilemínina stěna', 'Vyhlídka na území Jetřichovic. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 50.8633, 14.4036, 'CZ', 'wikidata-cs-batch2', 31182, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wilhelminenwand.jpg', '{"en": {"name": "Vilemínina stěna", "description": "A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Vilemínina stěna", "description": "Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Vilemínina stěna", "description": "Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Vilemínina stěna", "description": "Uitkijkpunt in Tsjechië. Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Vilemínina stěna", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Vilemínina stěna", "description": "Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Vilemínina stěna", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
